-- Conferencia: faturamento por mes das OS concluidas
SELECT FORMAT(COALESCE(DATA_EXECUCAO, DATA_ABERTURA), 'yyyy-MM') AS MES,
       COUNT(*)   AS QTD_OS,
       SUM(VALOR) AS FATURAMENTO
FROM ORDENS_SERVICOS
WHERE STATUS = 3
GROUP BY FORMAT(COALESCE(DATA_EXECUCAO, DATA_ABERTURA), 'yyyy-MM')
ORDER BY MES;
